const webhook = $(
  "Webhook - Get Analysis Status"
).first().json;

// 1. 获取前端请求的批次编号
const analysisRunId = String(
  webhook.query?.analysis_run_id ?? ""
).trim();

// 2. 校验请求参数
if (
  !analysisRunId ||
  analysisRunId.length > 128 ||
  !/^[A-Za-z0-9_-]+$/.test(analysisRunId)
) {
  return [
    {
      json: {
        success: false,
        found: false,
        analysis_run_id: analysisRunId || null,
        analysis_status: "invalid_request",
        analysis_stage: null,
        status_message: "缺少或无效的 analysis_run_id",
        failed_node: null,
        failure_reason: null,
        total_review_count: null,
        valid_review_count: null,
        updated_at: null
      }
    }
  ];
}

// 3. 读取 Data Table 查询结果
const rows = $input.all().map(item => item.json);

// Always Output Data 开启后，
// 未查到记录时可能会收到一个空对象 {}
const record = rows.find(row =>
  String(row.analysis_run_id ?? "").trim() === analysisRunId
);

// 4. 找不到记录：返回 not_found
if (!record) {
  return [
    {
      json: {
        success: true,
        found: false,
        analysis_run_id: analysisRunId,
        analysis_status: "not_found",
        analysis_stage: null,
        status_message: "未找到该批次的运行状态",
        failed_node: null,
        failure_reason: null,
        total_review_count: null,
        valid_review_count: null,
        updated_at: null
      }
    }
  ];
}

// 5. 找到记录：返回当前批次状态
return [
  {
    json: {
      success: true,
      found: true,

      analysis_run_id: analysisRunId,

      analysis_status:
        String(record.analysis_status ?? "unknown"),

      analysis_stage:
        record.analysis_stage ?? null,

      status_message:
        record.status_message ?? "",

      failed_node:
        String(record.analysis_stage ?? "").startsWith("error:")
          ? String(record.analysis_stage).slice(6)
          : null,

      failure_reason:
        String(record.analysis_status ?? "") === "failed"
          ? String(record.status_message ?? "")
          : null,

      total_review_count:
        record.total_review_count ?? null,

      valid_review_count:
        record.valid_review_count ?? null,

      updated_at:
        record.updated_at ?? null
    }
  }
];
